<section class="section"><div class="eyebrow">ADMIN ORDER DETAIL</div><h1><?=h($order['order_code'])?></h1><div class="detail-grid"><div class="stack"><div class="card"><h3>Customer</h3><p><b><?=h($order['customer_name'])?></b></p><p class="muted"><?=h($order['customer_email'])?></p></div><div class="card"><h3>Items</h3><?php foreach($items as $it): ?><div class="order-item"><img src="<?=h($it['image_url'])?>" alt="" onerror="this.style.display='none';this.parentElement.classList.add('photo-missing')"><div><b><?=h($it['product_name'])?></b><span><?=h($it['variant_name'])?></span><span><?=h($it['quantity'])?> × <?=rupiah($it['unit_price'])?></span></div></div><?php endforeach; ?></div><div class="card"><h3>Shipping address</h3><?php $addr=json_decode($order['address_json'],true); ?><p><?=h($addr['name'])?> · <?=h($addr['phone'])?></p><p class="muted"><?=h($addr['address'])?>, <?=h($addr['city'])?></p></div></div><div class="card"><h3>Order control</h3><div class="badge"><?=h($order['payment_status'])?></div><div class="badge"><?=h($order['status'])?></div><div class="summary-row"><span>Total</span><b><?=rupiah($order['total'])?></b></div><?php if($invoice): ?><a class="btn btn-outline full" href="<?=route_url('admin_invoice_download',['order_id'=>$order['id']])?>">Download invoice</a><?php else: ?><p class="muted">Invoice dibuat setelah pembayaran sukses.</p><?php endif; ?></div></div></section>